-- 行政紀錄備份使用獨立版本，不受查看提示與輸入提示干擾；不儲存備份副本。
ALTER TABLE system_meta ADD COLUMN backup_version INTEGER NOT NULL DEFAULT 1;
CREATE TRIGGER backup_admins_insert AFTER INSERT ON admins BEGIN UPDATE system_meta SET backup_version=backup_version+1 WHERE id=1; END;
CREATE TRIGGER backup_admins_update AFTER UPDATE ON admins BEGIN UPDATE system_meta SET backup_version=backup_version+1 WHERE id=1; END;
CREATE TRIGGER backup_admins_delete AFTER DELETE ON admins BEGIN UPDATE system_meta SET backup_version=backup_version+1 WHERE id=1; END;
